WITH row AS (INSERT INTO zc_private.discord_guild_feed (guild_id,kind,channel_id,enabled,cursor_event_id) VALUES($1,$2,$3,$4, (SELECT COALESCE(MAX(id),0) FROM public.discord_activity_event)) ON CONFLICT(guild_id,kind) DO UPDATE SET channel_id=excluded.channel_id,enabled=excluded.enabled, cursor_event_id=excluded.cursor_event_id,date_updated=clock_timestamp() RETURNING *) SELECT jsonb_build_object('guildId',guild_id::text,'kind',kind,'channelId',channel_id::text, 'enabled',enabled,'cursorEventId',cursor_event_id::text,'dateCreated',to_char(date_created AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM row
